import React, { useState, useEffect } from "react";
import { Input, Switch, Tooltip } from "antd";
import apiClient from "../../../../../api/client";
import ContentIcons1 from "./ContentComponents/ContentIcons1";
import { commitFilterModuleSettingsPatch } from "./filterSettingsSnapshot";
import {
  FILTER_RESET_DEFAULT_ICON,
  isEmptyIconValue,
} from "../../../filterModuleDefaults";
import {
  ResetModuleIconLockedSection,
  canUseResetModuleIcon,
} from "./shared/filterModuleTier";

const ModuleResetGeneral = (props) => {
  const path_url = tc_caf_ajax.plugin_path;
  let icons_url = path_url + "admin/fa-icons/fontawesome-5.json";
  const { rowindex, columnindex, moduleindex } = props.indexes;
  let settingData = {
    ...props.data[rowindex]?.data[columnindex]?.data[moduleindex]?.settings,
  };

  const [resetlabel, setResetlabel] = useState(settingData?.reset_label ?? "");
  const [resetIcon, setResetIcon] = useState(
    settingData?.icons?.visibility ?? false
  );
  const [iconsArray, setIconsArray] = useState("");

  useEffect(() => {
    const fetchIcons = async () => {
      try {
        const response = await apiClient.get(icons_url);
        if (response.data) {
          setIconsArray(response.data);
        }
      } catch (error) {
        console.error("Error ", error);
      }
    };

    fetchIcons();
  }, []);

  const handleChange = (val) => {
    setResetlabel(val);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        s.reset_label = val;
      },
    });
  };

  const handleResetIcon = (checked) => {
    if (!canUseResetModuleIcon()) {
      return;
    }
    setResetIcon(checked);
    commitFilterModuleSettingsPatch({
      data: props.data,
      rowindex,
      columnindex,
      moduleindex,
      onSettingChange: props.onSettingChange,
      patch: (s) => {
        const ic = { ...(s.icons || {}) };
        ic.visibility = checked;
        if (checked && isEmptyIconValue(ic.icon)) {
          ic.icon = FILTER_RESET_DEFAULT_ICON;
          ic.type = ic.type || "icon";
        }
        s.icons = ic;
      },
    });
  };

  const showResetIconControls = canUseResetModuleIcon() ? resetIcon : true;

  return (
    <>
      <div className="module-content-tab-row caf-design-two-half">
        <Tooltip
          classNames={{ root: "caf-builder-tooltip" }}
          placement="topLeft"
          title="Set reset button label."
        >
          <label>Text</label>
        </Tooltip>
        <Input
          onChange={(e) => handleChange(e.target.value)}
          value={resetlabel}
        />
      </div>

      <div className="caf-filter-label-inner-row">
        <ResetModuleIconLockedSection>
          <div className="module-content-tab-row caf-pad-20">
            <div className="module-content-tab-row caf-design-two-half">
              <Tooltip
                classNames={{ root: "caf-builder-tooltip" }}
                placement="topLeft"
                title="Enable or disable reset icon."
              >
                <label>Show Icon</label>
              </Tooltip>
              <Switch
                onChange={handleResetIcon}
                checked={canUseResetModuleIcon() ? resetIcon : true}
                disabled={!canUseResetModuleIcon()}
              />
            </div>
            {showResetIconControls && (
              <div className="module-content-tab-row caf-pad-10">
                {canUseResetModuleIcon() && iconsArray ? (
                  <ContentIcons1
                    title="Icons"
                    data={props.data}
                    indexes={props.indexes}
                    iconsArray={iconsArray}
                    onSettingChange={props.onSettingChange}
                    tab="reset_icon"
                    type=""
                  />
                ) : (
                  <div className="caf-reset-icon-locked-placeholder">
                    <i className="fas fa-undo" aria-hidden="true" />
                  </div>
                )}
              </div>
            )}
          </div>
        </ResetModuleIconLockedSection>
      </div>
    </>
  );
};

export default ModuleResetGeneral;
